#include <CoreAudio/CoreAudio.h>
#include <CoreFoundation/CoreFoundation.h>
#include <cstdio>
#include <cstdlib>
#include <vector>
#include <string>
#include <unistd.h>
static void check(OSStatus s,const char* op){if(s){fprintf(stderr,"%s failed: %d\n",op,s);exit(1);}}
static UInt32 u32(AudioDeviceID d,AudioObjectPropertySelector sel,AudioObjectPropertyScope scope){UInt32 v=0,size=sizeof(v);AudioObjectPropertyAddress a{sel,scope,kAudioObjectPropertyElementMain};check(AudioObjectGetPropertyData(d,&a,0,nullptr,&size,&v),"get u32");return v;}
int main(int argc,char** argv){AudioObjectPropertyAddress a{kAudioHardwarePropertyDevices,kAudioObjectPropertyScopeGlobal,kAudioObjectPropertyElementMain};UInt32 size=0;check(AudioObjectGetPropertyDataSize(kAudioObjectSystemObject,&a,0,nullptr,&size),"devices size");std::vector<AudioDeviceID> ds(size/sizeof(AudioDeviceID));check(AudioObjectGetPropertyData(kAudioObjectSystemObject,&a,0,nullptr,&size,ds.data()),"devices");AudioDeviceID d=0;for(auto item:ds){CFStringRef n=nullptr;size=sizeof(n);a={kAudioObjectPropertyName,kAudioObjectPropertyScopeGlobal,kAudioObjectPropertyElementMain};check(AudioObjectGetPropertyData(item,&a,0,nullptr,&size,&n),"name");char text[256]={};CFStringGetCString(n,text,sizeof(text),kCFStringEncodingUTF8);CFRelease(n);if(std::string(text)=="1248")d=item;}if(!d){fprintf(stderr,"MOTU1248 unavailable\n");return 2;}if(argc==2){UInt32 frames=atoi(argv[1]);if(frames!=256&&frames!=512){fprintf(stderr,"Only 256/512 accepted\n");return 3;}a={kAudioDevicePropertyBufferFrameSize,kAudioObjectPropertyScopeGlobal,kAudioObjectPropertyElementMain};check(AudioObjectSetPropertyData(d,&a,0,nullptr,sizeof(frames),&frames),"set buffer");for(int i=0;i<40&&u32(d,kAudioDevicePropertyBufferFrameSize,kAudioObjectPropertyScopeGlobal)!=frames;i++)usleep(50000);if(u32(d,kAudioDevicePropertyBufferFrameSize,kAudioObjectPropertyScopeGlobal)!=frames)return 4;}
Float64 rate=0;size=sizeof(rate);a={kAudioDevicePropertyNominalSampleRate,kAudioObjectPropertyScopeGlobal,kAudioObjectPropertyElementMain};check(AudioObjectGetPropertyData(d,&a,0,nullptr,&size,&rate),"sample rate");printf("{\"device\":%u,\"name\":\"1248\",\"sampleRate\":%.0f,\"hardwareFrames\":%u,\"inputLatencyFrames\":%u,\"outputLatencyFrames\":%u,\"inputSafetyOffsetFrames\":%u,\"outputSafetyOffsetFrames\":%u}\n",d,rate,u32(d,kAudioDevicePropertyBufferFrameSize,kAudioObjectPropertyScopeGlobal),u32(d,kAudioDevicePropertyLatency,kAudioObjectPropertyScopeInput),u32(d,kAudioDevicePropertyLatency,kAudioObjectPropertyScopeOutput),u32(d,kAudioDevicePropertySafetyOffset,kAudioObjectPropertyScopeInput),u32(d,kAudioDevicePropertySafetyOffset,kAudioObjectPropertyScopeOutput));}
